"use client"

import { Search, SlidersHorizontal } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { useState, useEffect } from "react"
import { Slider } from "@/components/ui/slider"
import { useRouter, useSearchParams, usePathname } from "next/navigation"


export function FilterBar() {
    const router = useRouter()
    const searchParams = useSearchParams()
    const pathname = usePathname()

    // Initialize state
    const [query, setQuery] = useState("")
    const [surfaceRange, setSurfaceRange] = useState([0, 300])
    const [priceRange, setPriceRange] = useState([500, 5000])

    // Sync from URL on mount/update
    useEffect(() => {
        setQuery(searchParams.get("q") || "")

        const minSurface = searchParams.get("minSurface") ? Number(searchParams.get("minSurface")) : 0
        const maxSurface = searchParams.get("maxSurface") ? Number(searchParams.get("maxSurface")) : 300
        setSurfaceRange([minSurface, maxSurface])

        const minPrice = searchParams.get("minPrice") ? Number(searchParams.get("minPrice")) : 500
        const maxPrice = searchParams.get("maxPrice") ? Number(searchParams.get("maxPrice")) : 5000
        setPriceRange([minPrice, maxPrice])
    }, [searchParams])

    const applyFilters = () => {
        const params = new URLSearchParams(searchParams)

        if (query) params.set("q", query)
        else params.delete("q")

        params.set("minSurface", surfaceRange[0].toString())
        params.set("maxSurface", surfaceRange[1].toString())

        params.set("minPrice", priceRange[0].toString())
        params.set("maxPrice", priceRange[1].toString())

        router.push(`${pathname}?${params.toString()}`, { scroll: false })
    }

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === "Enter") {
            applyFilters()
        }
    }

    return (
        <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-4 sticky top-24 z-10 mx-auto max-w-7xl w-full">
            <div className="flex flex-col lg:flex-row items-center gap-6">

                {/* Search Input */}
                <div className="relative w-full lg:w-[320px] shrink-0">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
                    <Input
                        placeholder="Ville, code postal..."
                        className="pl-10 h-11 bg-slate-50 border-slate-200 focus:bg-white transition-all w-full"
                        value={query}
                        onChange={(e) => setQuery(e.target.value)}
                        onKeyDown={handleKeyDown}
                    />
                </div>

                <div className="h-px w-full lg:w-px lg:h-10 bg-slate-100 hidden lg:block" />

                {/* Filters Group */}
                <div className="flex flex-1 flex-col md:flex-row items-center gap-6 w-full">

                    {/* Surface Slider */}
                    <div className="w-full space-y-3">
                        <div className="flex items-center justify-between text-sm">
                            <span className="font-semibold text-[#12182C]">Surface</span>
                            <span className="text-slate-500 font-medium">
                                {surfaceRange[0]} - {surfaceRange[1]} m┬▓ {surfaceRange[1] === 300 && "+"}
                            </span>
                        </div>
                        <Slider
                            defaultValue={[0, 300]}
                            max={300}
                            step={5}
                            value={surfaceRange}
                            onValueChange={setSurfaceRange}
                            className="py-2"
                        />
                    </div>

                    <div className="h-px w-full md:w-px md:h-10 bg-slate-100 hidden md:block" />

                    {/* Price Slider */}
                    <div className="w-full space-y-3">
                        <div className="flex items-center justify-between text-sm">
                            <span className="font-semibold text-[#12182C]">Loyer</span>
                            <span className="text-slate-500 font-medium">
                                {priceRange[0]} - {priceRange[1]} Ôé¼ {priceRange[1] === 5000 && "+"}
                            </span>
                        </div>
                        <Slider
                            defaultValue={[500, 5000]}
                            max={5000}
                            step={50}
                            value={priceRange}
                            onValueChange={setPriceRange}
                            className="py-2"
                        />
                    </div>
                </div>

                {/* Action Button */}
                <Button
                    onClick={applyFilters}
                    className="w-full lg:w-auto h-11 px-8 bg-[#3153A1] hover:bg-[#25468d] text-white font-medium rounded-lg shadow-lg shadow-blue-900/20 shrink-0 transition-all active:scale-95"
                >
                    <SlidersHorizontal className="h-4 w-4 mr-2" />
                    Filtrer
                </Button>
            </div>
        </div>
    )
}

import * as React from "react"
import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"

export interface PhoneInputProps
    extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'onChange'> {
    defaultValue?: string;
}

export const PhoneInput = React.forwardRef<HTMLInputElement, PhoneInputProps>(
    ({ className, name, id, defaultValue = "", required, ...props }, ref) => {
        // Extract prefix and number if defaultValue exists
        const match = defaultValue.match(/^(\+\d{2,3})(.*)$/)
        const initialPrefix = match ? match[1] : "+33"
        const initialNumber = match ? match[2].trim() : defaultValue.replace(/^\+33/, "")

        const [prefix, setPrefix] = React.useState(initialPrefix)
        const [number, setNumber] = React.useState(initialNumber)

        // Hidden input combines them for the native form submission
        const combinedValue = `${prefix}${number.replace(/\s/g, "")}`

        const handleNumberChange = (e: React.ChangeEvent<HTMLInputElement>) => {
            // Allow only numbers
            const val = e.target.value.replace(/[^0-9]/g, "")
            setNumber(val)
        }

        return (
            <div className={cn("flex relative", className)}>
                <select
                    value={prefix}
                    onChange={(e) => setPrefix(e.target.value)}
                    className="h-11 rounded-l-md border border-r-0 border-slate-200 bg-slate-50 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-slate-950 focus:border-transparent transition-colors z-10"
                >
                    <option value="+33">­ƒç½­ƒçÀ +33</option>
                    <option value="+213">­ƒç®­ƒç┐ +213</option>
                    <option value="+32">­ƒçº­ƒç¬ +32</option>
                    <option value="+41">­ƒç¿­ƒç¡ +41</option>
                    <option value="+44">­ƒç¼­ƒçº +44</option>
                    <option value="+1">­ƒç║­ƒç© +1</option>
                    <option value="+212">­ƒç▓­ƒçª +212</option>
                    <option value="+216">­ƒç╣­ƒç│ +216</option>
                </select>

                <Input
                    type="tel"
                    className="rounded-l-none pl-3 h-11"
                    placeholder="0612345678"
                    value={number}
                    onChange={handleNumberChange}
                    maxLength={15}
                    {...props}
                />

                <input
                    type="hidden"
                    name={name}
                    id={id}
                    value={combinedValue}
                    required={required && number.length === 0}
                />
            </div>
        )
    }
)
PhoneInput.displayName = "PhoneInput"
